const now = new Date();
const etString = now.toLocaleString('en-US', { timeZone: 'America/New_York' });
const etDate = new Date(etString);
const hours = etDate.getHours();
const minutes = etDate.getMinutes();
const month = etDate.getMonth() + 1;
const day = etDate.getDate();
const dayOfWeek = etDate.getDay();
const year = etDate.getFullYear();
const dateStr = `${year}-${String(month).padStart(2,'0')}-${String(day).padStart(2,'0')}`;

if (dayOfWeek === 0 || dayOfWeek === 6) {
  return [];
}

const holidays2026 = [
  '2026-01-01', '2026-01-19', '2026-02-16', '2026-04-03', '2026-05-25',
  '2026-06-19', '2026-07-03', '2026-09-07', '2026-11-26', '2026-12-25'
];

if (holidays2026.includes(dateStr)) {
  return [];
}

const timeInMinutes = hours * 60 + minutes;
const MARKET_OPEN = 9 * 60 + 30;
const MARKET_CLOSE = 16 * 60;

if (timeInMinutes < MARKET_OPEN || timeInMinutes >= MARKET_CLOSE) {
  return [];
}

return [{
  json: {
    marketOpen: true,
    timestamp: now.toISOString(),
    etTime: `${hours}:${String(minutes).padStart(2, '0')}`,
    dateStr: dateStr,
    scanType: 'CSP_DAILY'
  }
}];

// ============================================================
// FUNDAMENTAL QUALITY SCREEN (FIXED)
// ============================================================
// Receives merged data from both FMP HTTP nodes via Merge node
// ============================================================

const allItems = $input.all();
const allQuotes = [];

for (const item of allItems) {
  const data = item.json;
  if (Array.isArray(data)) {
    allQuotes.push(...data);
  } else if (data && data.symbol) {
    allQuotes.push(data);
  }
}

const vixArray = [];
const quotesArray = [];

for (const q of allQuotes) {
  if (!q || !q.symbol) continue;
  if (q.symbol === '^VIX' || q.symbol === 'VIX') {
    vixArray.push(q);
  } else if (q.symbol !== 'SPY') {
    quotesArray.push(q);
  }
}

let triggerData = null;
try {
  const node = $('Market Hours Check');
  if (node && node.first()) {
    triggerData = node.first().json;
  }
} catch (e) {}

if (!triggerData || !triggerData.dateStr) {
  const now = new Date();
  const etDate = new Date(now.toLocaleString('en-US', { timeZone: 'America/New_York' }));
  triggerData = {
    dateStr: `${etDate.getFullYear()}-${String(etDate.getMonth()+1).padStart(2,'0')}-${String(etDate.getDate()).padStart(2,'0')}`,
    timestamp: now.toISOString()
  };
}

const vixQuote = vixArray.find(q => q.symbol === '^VIX' || q.symbol === 'VIX');
const vix = vixQuote ? vixQuote.price : 20;

let regime, sizingPct;
if (vix < 15) { regime = 'LOW'; sizingPct = 75; }
else if (vix <= 25) { regime = 'NORMAL'; sizingPct = 100; }
else if (vix <= 35) { regime = 'ELEVATED'; sizingPct = 50; }
else { regime = 'CRISIS'; sizingPct = 25; }

const SECTORS = {
  'AAPL': 'Technology', 'MSFT': 'Technology', 'GOOGL': 'Technology',
  'AMZN': 'Technology', 'AVGO': 'Technology', 'META': 'Technology',
  'NVDA': 'Technology', 'V': 'Financial', 'MA': 'Financial',
  'COST': 'Consumer Defensive', 'SPY': 'Index'
};

const qualifying = [];
const rejected = [];

for (const q of quotesArray) {
  const ticker = q.symbol;
  if (!ticker) continue;

  const reasons = [];

  if (q.priceAvg50 && q.price < q.priceAvg50) {
    reasons.push(`Below 50-day SMA ($${q.price.toFixed(2)} < $${q.priceAvg50.toFixed(2)})`);
  }

  if (q.changesPercentage && q.changesPercentage > 8) {
    reasons.push(`Overbought today (+${q.changesPercentage.toFixed(1)}%)`);
  }

  if (!q.volume || q.volume < 100000) {
    reasons.push(`Low/no volume (${q.volume || 0})`);
  }

  if (reasons.length === 0) {
    qualifying.push({
      ticker, price: q.price, priceAvg50: q.priceAvg50, priceAvg200: q.priceAvg200,
      changesPercentage: q.changesPercentage, volume: q.volume, avgVolume: q.avgVolume,
      marketCap: q.marketCap, yearHigh: q.yearHigh, yearLow: q.yearLow,
      sector: SECTORS[ticker] || 'Unknown'
    });
  } else {
    rejected.push({ ticker, reasons });
  }
}

return [{
  json: {
    qualifying, rejected,
    qualifyingCount: qualifying.length,
    rejectedCount: rejected.length,
    vix, regime, sizingPct,
    dateStr: triggerData.dateStr,
    timestamp: triggerData.timestamp
  }
}];

const screenData = $('Fundamental Quality Screen').first().json;
const earningsRaw = $('FMP: Earnings Calendar (Next 45 Days)').first().json;

const earningsArray = Array.isArray(earningsRaw) ? earningsRaw : [];
const UNIVERSE = ['AAPL','MSFT','GOOGL','AMZN','AVGO','COST','V','MA','META','NVDA','SPY'];

const earningsTickers = new Set();
const earningsDetails = {};

for (const e of earningsArray) {
  if (UNIVERSE.includes(e.symbol)) {
    earningsTickers.add(e.symbol);
    earningsDetails[e.symbol] = {
      date: e.date,
      epsEstimated: e.epsEstimated,
      revenueEstimated: e.revenueEstimated
    };
  }
}

const cleared = [];
const earningsExcluded = [];

for (const q of screenData.qualifying) {
  if (earningsTickers.has(q.ticker)) {
    earningsExcluded.push({
      ticker: q.ticker,
      earningsDate: earningsDetails[q.ticker].date,
      reason: `Earnings on ${earningsDetails[q.ticker].date} - within DTE window`
    });
  } else {
    cleared.push(q);
  }
}

return [{
  json: {
    cleared, earningsExcluded,
    clearedCount: cleared.length,
    excludedCount: earningsExcluded.length,
    vix: screenData.vix,
    regime: screenData.regime,
    sizingPct: screenData.sizingPct,
    rejected: screenData.rejected,
    dateStr: screenData.dateStr,
    timestamp: screenData.timestamp
  }
}];

const data = $('Filter Earnings Conflicts').first().json;
const cleared = data.cleared;

if (!cleared || cleared.length === 0) {
  return [{
    json: {
      chains: [], chainCount: 0,
      vix: data.vix, regime: data.regime, sizingPct: data.sizingPct,
      earningsExcluded: data.earningsExcluded,
      rejected: data.rejected,
      dateStr: data.dateStr, timestamp: data.timestamp
    }
  }];
}

const FMP_API_KEY = 'FAAjnYQTvfGg8j7RoPSvHYRVtSKTvJyz';
const chains = [];

for (const ticker of cleared) {
  const strikeMin = Math.floor(ticker.price * 0.85);
  const strikeMax = Math.ceil(ticker.price * 0.97);
  let contracts = [];
  let source = '';

  try {
    const fmpUrl = `https://financialmodelingprep.com/api/v4/options-chain/${ticker.ticker}?apikey=${FMP_API_KEY}`;
    const fmpResp = await fetch(fmpUrl, { method: 'GET', signal: AbortSignal.timeout(8000) });

    if (fmpResp.ok) {
      const fmpData = await fmpResp.json();
      const filtered = (Array.isArray(fmpData) ? fmpData : []).filter(o => {
        const isPut = (o.type === 'put' || o.putCall === 'put' || o.side === 'put');
        const inRange = o.strike >= strikeMin && o.strike <= strikeMax;
        return isPut && inRange;
      });
      contracts = filtered;
      source = 'fmp';
    }
  } catch (err) {
    source = 'failed';
  }

  chains.push({
    ticker: ticker.ticker, price: ticker.price, sector: ticker.sector,
    priceAvg50: ticker.priceAvg50, yearHigh: ticker.yearHigh, yearLow: ticker.yearLow,
    contracts, contractCount: contracts.length, source
  });
}

return [{
  json: {
    chains, chainCount: chains.length,
    vix: data.vix, regime: data.regime, sizingPct: data.sizingPct,
    earningsExcluded: data.earningsExcluded, rejected: data.rejected,
    dateStr: data.dateStr, timestamp: data.timestamp
  }
}];

const data = $('Fetch Options Chains').first().json;
const chains = data.chains || [];
const PORTFOLIO_VALUE = 100000;
const MAX_POSITION_PCT = 0.05;
const MAX_SECTOR_POSITIONS = 3;
const MAX_SECTOR_EXPOSURE_PCT = 0.25;
const today = new Date();

function normalizeContract(c) {
  return {
    strike: c.strike || c.strikePrice,
    bid: c.bid || c.bidPrice || 0,
    ask: c.ask || c.askPrice || 0,
    delta: c.delta || null,
    iv: c.impliedVolatility || c.iv || null,
    openInterest: c.openInterest || 0,
    volume: c.volume || 0,
    expiration: c.expiration || c.expirationDate,
    dte: c.dte || c.daysToExpiration || null
  };
}

function calcDTE(exp) {
  if (!exp) return null;
  return Math.ceil((new Date(exp).getTime() - today.getTime()) / (1000*60*60*24));
}

const allOpportunities = [];

for (const chain of chains) {
  if (!chain.contracts || chain.contracts.length === 0) continue;

  for (const raw of chain.contracts) {
    const c = normalizeContract(raw);
    const dte = c.dte || calcDTE(c.expiration);
    if (!dte || dte < 30 || dte > 45) continue;
    const absDelta = Math.abs(c.delta || 0);
    if (absDelta < 0.20 || absDelta > 0.30) continue;
    if (!c.bid || c.bid <= 0 || (c.openInterest || 0) < 10) continue;

    const premium = c.bid;
    const strike = c.strike;
    const annualizedReturn = (premium / strike) * (365 / dte) * 100;
    const collateralPerContract = strike * 100;
    const maxAllocation = PORTFOLIO_VALUE * MAX_POSITION_PCT * (data.sizingPct / 100);
    const maxContracts = Math.floor(maxAllocation / collateralPerContract);
    if (maxContracts < 1) continue;

    let ivRankProxy = c.iv ? Math.min(100, Math.max(0, ((c.iv - 0.15) / 0.35) * 100)) : 50;
    if (ivRankProxy < 30) continue;

    const returnScore = Math.min(100, Math.max(0, (annualizedReturn - 8) / 32 * 100));
    const liquidityScore = Math.min(100, (c.openInterest / 1000 + c.volume / 100) * 25);
    let trendScore = chain.yearHigh ? Math.min(100, (chain.price / chain.yearHigh) * 100) : 70;
    const compositeScore = returnScore * 0.40 + ivRankProxy * 0.30 + liquidityScore * 0.20 + trendScore * 0.10;

    allOpportunities.push({
      ticker: chain.ticker, sector: chain.sector, currentPrice: chain.price,
      strike, expiration: c.expiration, dte, bid: premium, ask: c.ask,
      delta: c.delta, absDelta, iv: c.iv, ivRankProxy: Math.round(ivRankProxy),
      openInterest: c.openInterest, volume: c.volume,
      annualizedReturn: Math.round(annualizedReturn * 100) / 100,
      breakeven: Math.round((strike - premium) * 100) / 100,
      maxLossPerContract: Math.round((strike - premium) * 100),
      collateralPerContract: Math.round(collateralPerContract),
      maxContracts, totalPremium: Math.round(premium * maxContracts * 100),
      totalCollateral: Math.round(collateralPerContract * maxContracts),
      compositeScore: Math.round(compositeScore * 100) / 100,
      returnScore: Math.round(returnScore * 100) / 100,
      ivScore: Math.round(ivRankProxy * 100) / 100,
      liquidityScore: Math.round(liquidityScore * 100) / 100,
      trendScore: Math.round(trendScore * 100) / 100,
      profitTarget: Math.round(premium * 0.50 * 100) / 100,
      stopLoss: Math.round(premium * 2.00 * 100) / 100,
      source: chain.source
    });
  }
}

allOpportunities.sort((a, b) => b.compositeScore - a.compositeScore);

const sectorCount = {};
const sectorExposure = {};
const top3 = [];
const sectorWarnings = [];

for (const opp of allOpportunities) {
  if (top3.length >= 3) break;
  const sector = opp.sector;
  const cnt = sectorCount[sector] || 0;
  const exp = sectorExposure[sector] || 0;
  const posExp = opp.totalCollateral / PORTFOLIO_VALUE;

  if (cnt >= MAX_SECTOR_POSITIONS) {
    sectorWarnings.push(`${opp.ticker}: Skipped - ${sector} has ${MAX_SECTOR_POSITIONS} positions`);
    continue;
  }
  if (exp + posExp > MAX_SECTOR_EXPOSURE_PCT) {
    sectorWarnings.push(`${opp.ticker}: Skipped - ${sector} would exceed 25%`);
    continue;
  }

  sectorCount[sector] = cnt + 1;
  sectorExposure[sector] = exp + posExp;
  opp.rank = top3.length + 1;
  top3.push(opp);
}

const totalCollateralDeployed = top3.reduce((s, o) => s + o.totalCollateral, 0);
const cashAfterTrades = PORTFOLIO_VALUE - totalCollateralDeployed;

return [{
  json: {
    top3, totalScanned: allOpportunities.length,
    sectorCount, sectorExposure, sectorWarnings,
    totalCollateralDeployed,
    totalPremiumCollected: top3.reduce((s, o) => s + o.totalPremium, 0),
    cashAfterTrades,
    cashPct: Math.round((cashAfterTrades / PORTFOLIO_VALUE) * 100),
    vix: data.vix, regime: data.regime, sizingPct: data.sizingPct,
    earningsExcluded: data.earningsExcluded || [],
    rejected: data.rejected || [],
    dateStr: data.dateStr,
    portfolioValue: PORTFOLIO_VALUE
  }
}];

const data = $('CSP Opportunity Scorer').first().json;
const top3 = data.top3 || [];

if (top3.length === 0) {
  const msg = [
    `📊 CSP DAILY SCAN — ${data.dateStr}`,
    `VIX: ${data.vix.toFixed(1)} (${data.regime}) | Sizing: ${data.sizingPct}%`,
    '', '⚠️ No qualifying CSP opportunities today.', '',
    `Scanned: ${data.totalScanned || 0} contracts`
  ];
  if (data.earningsExcluded?.length > 0) {
    msg.push('', 'Earnings exclusions:');
    data.earningsExcluded.forEach(e => msg.push(`  • ${e.ticker}: ${e.earningsDate}`));
  }
  if (data.rejected?.length > 0) {
    msg.push('', 'Quality screen rejections:');
    data.rejected.forEach(r => msg.push(`  • ${r.ticker}: ${r.reasons.join(', ')}`));
  }
  return [{ json: { text: msg.join('\n'), hasOpportunities: false } }];
}

const medals = ['🥇', '🥈', '🥉'];
const lines = [
  `📊 CSP DAILY SCAN — ${data.dateStr}`,
  `VIX: ${data.vix.toFixed(1)} (${data.regime}) | Sizing: ${data.sizingPct}%`,
  `Scanned: ${data.totalScanned} contracts`, ''
];

top3.forEach((o, i) => {
  lines.push(`${medals[i]} #${i+1} ${o.ticker} $${o.strike}P ${o.expiration}`);
  lines.push(`  Credit: $${o.bid.toFixed(2)} | Delta: ${o.delta?.toFixed(3) || 'N/A'} | DTE: ${o.dte}`);
  lines.push(`  Annual Return: ${o.annualizedReturn}% | Breakeven: $${o.breakeven}`);
  lines.push(`  Score: ${o.compositeScore} | Contracts: ${o.maxContracts} | Collateral: $${o.totalCollateral.toLocaleString()}`);
  lines.push('');
});

lines.push('⚠️ Risk Checks:');
if (data.sectorExposure) {
  Object.entries(data.sectorExposure).forEach(([s, e]) => lines.push(`  • ${s}: ${(e*100).toFixed(1)}%`));
}
lines.push(`  • Total collateral: $${data.totalCollateralDeployed.toLocaleString()} (${((data.totalCollateralDeployed/data.portfolioValue)*100).toFixed(1)}%)`);
lines.push(`  • Cash after: $${data.cashAfterTrades.toLocaleString()} (${data.cashPct}%)`);
lines.push('', 'Use /paper-trade to log a trade.');

return [{ json: { text: lines.join('\n'), hasOpportunities: true, top3, dateStr: data.dateStr } }];

const alertData = $('Format Telegram Alert').first().json;
const scorerData = $('CSP Opportunity Scorer').first().json;
const top3 = scorerData.top3 || [];

return [{ json: {
  Date: scorerData.dateStr, VIX: scorerData.vix, Regime: scorerData.regime,
  'Sizing%': scorerData.sizingPct,
  Ticker1: top3[0]?.ticker||'', Strike1: top3[0]?.strike||'', Expiry1: top3[0]?.expiration||'',
  Premium1: top3[0]?.bid||'', Delta1: top3[0]?.delta||'', AnnReturn1: top3[0]?.annualizedReturn||'',
  Score1: top3[0]?.compositeScore||'',
  Ticker2: top3[1]?.ticker||'', Strike2: top3[1]?.strike||'', Premium2: top3[1]?.bid||'',
  Ticker3: top3[2]?.ticker||'', Strike3: top3[2]?.strike||'', Premium3: top3[2]?.bid||'',
  TotalCollateral: scorerData.totalCollateralDeployed||0,
  'Cash%': scorerData.cashPct||100,
  ContractsScanned: scorerData.totalScanned||0,
  Notes: alertData.hasOpportunities ? `${top3.length} opportunities` : 'No opportunities'
}}];
